@st.cache_data(ttl=30)
def load(path):
    return pl.read_parquet(path).to_pandas() if path.exists() else None

def has(v): return pd.notna(v)
def yes(v): return bool(v) if has(v) else False
def esc(v): return html.escape(str(v)) if has(v) else "—"
def n(v,d=1): return "—" if not has(v) else f"{float(v):.{d}f}"

def pick(r, name):
    if str(r.get("pipeline_status","")).upper()=="FROZEN":
        ov=r.get("official_"+name)
        if has(ov): return ov
    return r.get(name)

def line(home,away,x,digits=1):
    """Project home-margin convention into conventional favorite notation."""
    if not has(x): return "—"
    x=float(x)
    if abs(x) < 1e-12: return "PK"
    team = home if x > 0 else away
    return f"{team} -{abs(x):.{digits}f}"

def actual_result(home, away, home_margin):
    """Final straight-up margin, not ATS grade. Example: DEN -7."""
    return line(home, away, home_margin, 1)

def final_score_from_row(r):
    """Compact final score using score columns when present, with home_margin fallback."""
    home = r.get("home_team")
    away = r.get("away_team")
    hs = r.get("home_score")
    aws = r.get("away_score")

    # Preferred source: explicit final scores.
    if has(hs) and has(aws):
        return f"{away} {int(float(aws))} – {home} {int(float(hs))}"

    # 2025 historical UI source can lack score columns even though home_margin is present.
    # Recover the score from common nflverse final-score aliases if they survived a join.
    for hcol, acol in [
        ("home_score_display", "away_score_display"),
        ("home_score_y", "away_score_y"),
        ("home_score_x", "away_score_x"),
        ("result_home_score", "result_away_score"),
    ]:
        h = r.get(hcol)
        a = r.get(acol)
        if has(h) and has(a):
            return f"{away} {int(float(a))} – {home} {int(float(h))}"

    return "—"

def elway_bet(home, away, spread_line, predicted_home_margin):
    """Actual ATS wager implied by Elway's market disagreement."""
    if not has(spread_line) or not has(predicted_home_margin):
        return "—"
    spread = float(spread_line)
    pred = float(predicted_home_margin)

    # Internal convention: spread_line is market home margin.
    if pred > spread:
        pts = -spread
        return f"{home} {pts:+.1f}" if abs(pts) > 1e-12 else f"{home} PK"
    if pred < spread:
        pts = spread
        return f"{away} {pts:+.1f}" if abs(pts) > 1e-12 else f"{away} PK"
    return "PASS"

def pill(text, cls=""):
    return f'<span class="pill {cls}">{text}</span>'

def ats_pill(v):
    if not has(v): return ""
    s=str(v).upper()
    if s=="PASS": return ""
    cls="win" if s.startswith("W") else "loss" if s.startswith("L") else "push"
    return pill(f"ATS {s}",cls)

def card(r, season):
    historical=season in {2023, 2024, 2025}
    status=str(r.get("pipeline_status","HISTORICAL")).upper()
    edge=pick(r,"edge_size"); pred=pick(r,"predicted_home_margin"); spread=pick(r,"spread_line")
    dist=pick(r,"football_distance")
    context=yes(pick(r,"high_unusual"))
    margin5=has(edge) and float(edge) >= 5.0

    # 2023-2025: retrospective application of the frozen 2026 screen.
    # 2026: only call it ELWAY EDGE once governance has made it official/frozen.
    retro_screen=yes(r.get("retrospective_regime_match")) if historical else False
    live_screen=(status=="FROZEN" and yes(pick(r,"frozen_signal"))) if not historical else False
    elway_edge = retro_screen or live_screen

    cls="game" + (" frozen" if status=="FROZEN" else "") + (" signal" if elway_edge else "")
    badges=""

    if historical:
        badges += pill("HISTORICAL","histpill")
        if context: badges += pill("CONTEXT CLUES","contextpill")
        if margin5: badges += pill("5+ MARGIN","marginpill")
        if elway_edge: badges += pill("ELWAY EDGE ✓","edgepill")
        badges += ats_pill(r.get("ats_result"))
    else:
        badges += pill(status,status.lower())
        for lab,col in [("MARKET","market_ready"),("PBP","pbp_ready"),("QB1","qb1_ready")]:
            badges += pill(f"{lab} {'✓' if yes(r.get(col)) else '…'}","ok" if yes(r.get(col)) else "wait")
        # Show Elway model readiness/output for every 2026 week when available.
        # Governance remains unchanged: only READY/FROZEN rows can receive governed
        # context/margin badges, and only FROZEN rows can receive ELWAY EDGE ✓.
        badges += pill(f"ELWAY {'✓' if yes(r.get('elway_ready')) else '…'}","ok" if yes(r.get("elway_ready")) else "wait")
        if status in {"READY","FROZEN"} and context: badges += pill("CONTEXT CLUES","contextpill")
        if status in {"READY","FROZEN"} and margin5: badges += pill("5+ MARGIN","marginpill")
        if live_screen: badges += pill("ELWAY EDGE ✓","edgepill")
        # ATS appears only after an outcome exists and if a graded result is available.
        badges += ats_pill(r.get("ats_result"))

    meta=" • ".join([str(x) for x in [r.get("gameday"),r.get("gametime"),r.get("stadium")] if has(x)])
    # Browsing/reference: display available Elway model outputs for all 2026 weeks.
    # This is display-only and does not change MONITOR/READY/FROZEN governance.
    show_model = historical or season == 2026
    grid=f"""<div class="grid">
    <div><div class="ml">Market</div><div class="mv">{line(r["home_team"],r["away_team"],spread)}</div></div>
    <div><div class="ml">Elway Says</div><div class="mv">{line(r["home_team"],r["away_team"],pred)}</div></div>
    <div><div class="ml">Elway Bet</div><div class="mv">{elway_bet(r["home_team"],r["away_team"],spread,pred)}</div></div>
    <div><div class="ml">Edge Margin</div><div class="mv">{n(edge,2)}</div></div>
    <div><div class="ml">Context Clues</div><div class="mv">{n(dist,2)}</div></div>
    <div><div class="ml">Final Score</div><div class="mv">{final_score_from_row(r)}</div></div>
    <div><div class="ml">Actual Result</div><div class="mv">{actual_result(r["home_team"],r["away_team"],r.get("home_margin"))}</div></div>
    </div>""" if show_model else """<div class="small" style="margin-top:12px;padding-top:11px;border-top:1px solid var(--border)">
    Early-season runway • schedule and data monitoring only.</div>"""

    st.markdown(f"""<div class="{cls}"><div class="top"><div class="label">Week {int(r["week"])}</div>
    </div><div class="match">{esc(r["away_team"])} <span class="at">@</span> {esc(r["home_team"])}</div>
    <div class="meta">{esc(meta) if meta else ""}</div><div class="pills">{badges}</div>{grid}</div>""",
    unsafe_allow_html=True)

st.markdown(
    """<div class="brand-wrap">
    <img class="brand-logo" src="data:image/png;base64," alt="HumBets Elway Edge">
    </div>""",
    unsafe_allow_html=True,
)
st.markdown(
    "<div class=\"sub\">NFL • HumBets' Elway Edge • Identifying angles using Jon Humbert's proprietary model</div>",
    unsafe_allow_html=True,
)

available=[]
if PHIST.exists():
    h=load(PHIST)
    if h is not None and "season" in h:
        available += sorted(int(x) for x in h["season"].dropna().unique())
if P26.exists(): available.append(2026)
available=sorted(set(available))
if not available:
    st.error("No HumBets browser datasets found.")
    st.code("python3 build_humbets_historical_2023_2025.py\npython3 refresh_humbets_2026.py\npython3 humbets_2026_pipeline_validation.py")
    st.stop()

season=st.segmented_control("Season",available,default=max(available),key="season")
if season < 2026:
    all_hist=load(PHIST)
    df=all_hist[all_hist.season==season].copy()
else:
    df=load(P26)

if season < 2026:
    st.markdown(f'<div class="era hist"><b>{season} · HISTORICAL</b><br><span class="small">Completed results and backtested Elway analysis. ELWAY EDGE identifies games that satisfied all proprietary model criteria. It is not prospective to future seasons.</span></div>',unsafe_allow_html=True)
else:
    st.markdown('<div class="era live"><b>2026 · LIVE / PROSPECTIVE</b><br><span class="small">Weeks 1–4 are for data gathering. Weeks 5+ use the ELWAY EDGE.</span></div>',unsafe_allow_html=True)

if season < 2026:
    total=len(df)
    decisions=int(df["ats_result"].notna().sum()) if "ats_result" in df else 0
    regimes=int(df["retrospective_regime_match"].fillna(False).sum()) if "retrospective_regime_match" in df else 0
    mae=(df["predicted_home_margin"]-df["home_margin"]).abs().mean() if {"predicted_home_margin","home_margin"}<=set(df.columns) else float("nan")
    a,b,c=st.columns(3)
    a.metric("Historical games",total)
    b.metric("Elway Edge games",regimes)
    c.metric("Elway MAE",f"{mae:.2f}" if has(mae) else "—")
else:
    a,b,c,d,e=st.columns(5)
    a.metric("Schedule",f"{len(df)} games")
    a_final=(df["home_score"].notna()&df["away_score"].notna()).sum()
    b.metric("Final",int(a_final)); c.metric("PBP loaded",int(df["pbp_ready"].fillna(False).sum()))
    d.metric("Market lines",int(df["market_ready"].fillna(False).sum()))
    e.metric("Frozen",int((df["pipeline_status"]=="FROZEN").sum()))

nav1,nav2=st.columns([2,1])
with nav1:
    mode=st.segmented_control("Browse",["By week","By team"],default="By week",key=f"browse_{season}")
with nav2:
    details=st.toggle("Details",False,key=f"details_{season}")

if mode=="By week":
    weeks=sorted(int(x) for x in df.week.dropna().unique())
    default=weeks[-1] if season < 2026 else next((w for w in weeks if df[df.week==w]["home_score"].isna().any()),weeks[-1])
    week=st.select_slider("Week",weeks,value=default,key=f"week_{season}")
    view=df[df.week==week].sort_values(["game_id"])
    st.markdown(f'<div class="kick">{season} • Week {week}</div>',unsafe_allow_html=True)
    st.subheader("Game board")
else:
    teams=sorted(set(df.home_team.dropna())|set(df.away_team.dropna()))
    team=st.selectbox("Team",teams,key=f"team_{season}")
    view=df[(df.home_team==team)|(df.away_team==team)].sort_values(["week","game_id"])
    st.markdown(f'<div class="kick">{team} • {season}</div>',unsafe_allow_html=True)
    st.subheader("Season schedule")

for _,r in view.iterrows():
    card(r.to_dict(),season)

if details:
    st.divider()
    if season < 2026:
        cols=[c for c in ["week","away_team","home_team","spread_line","predicted_home_margin","edge_size",
        "football_distance","high_unusual","retrospective_regime_match","home_margin","ats_result",
        "elway_abs_error","market_abs_error","closer_forecast"] if c in df]
    else:
        cols=[c for c in ["week","away_team","home_team","pipeline_status","pipeline_reason","market_ready",
        "pbp_ready","qb1_ready","elway_ready","football_distance","edge_size"] if c in df]
    st.dataframe(df[cols],use_container_width=True,hide_index=True)

with st.expander("What the labels mean"):
    st.markdown("""**CONTEXT CLUES** = the Football Distance value used to identify unusual matchup context. The bubble appears when the matchup clears the frozen HIGH_UNUSUAL threshold.

**ELWAY SAYS** = Elway's projected game line.

**ELWAY BET** = the actual ATS side and market spread Elway prefers; this is the wager graded by ATS WIN / LOSS / PUSH.

**5+ MARGIN** = Elway differs from the market by at least 5 points.

**ELWAY EDGE ✓** = the full screen is satisfied: 5+ MARGIN **and** CONTEXT CLUES.
In 2023–2025 this is retrospective. In 2026 it is only displayed as an official Elway Edge after the governed prediction is frozen.

**ATS WIN / LOSS / PUSH** = the realized against-the-spread outcome for the side Elway preferred.
This is an outcome, not part of the screen.

**ACTUAL RESULT** = the final straight-up scoring margin expressed in conventional team notation
(e.g. `DEN -7`). It is separate from the ATS grade.""")

source=PHIST if season < 2026 else P26
st.caption(f"Source: {source} • updated {datetime.fromtimestamp(source.stat().st_mtime):%b %d, %Y %I:%M %p}")
